const { PDF_BASE64, TEXT } = process.env;
if (!TEXT) { throw new Error('Missing required input TEXT'); }
globalThis.text = TEXT;
if (PDF_BASE64) {
  const buf = Buffer.from(PDF_BASE64, 'base64');
  globalThis.inputPdfBytes = new Uint8Array(buf);
} else {
  globalThis.inputPdfBytes = null;
}

const { PDFDocument, StandardFonts, rgb } = await import('pdf-lib');
let pdfDoc;
if (globalThis.inputPdfBytes) {
  pdfDoc = await PDFDocument.load(globalThis.inputPdfBytes);
} else {
  pdfDoc = await PDFDocument.create();
}
const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
let page;
if (pdfDoc.getPageCount() > 0) {
  page = pdfDoc.getPages()[0];
} else {
  page = pdfDoc.addPage();
}
page.drawText(globalThis.text, { x: 50, y: 700, size: 24, font, color: rgb(0, 0, 0) });
const pdfBytes = await pdfDoc.save();
globalThis.resultBase64 = Buffer.from(pdfBytes).toString('base64');
